// Injected fetch-based httpRequest shim (task-runner-safe)
const __helpers = this.helpers;
async function __httpRequest(opts) {
  const method = (opts.method || 'GET').toUpperCase();
  const url = opts.url;
  const headers = Object.assign({}, opts.headers || {});
  const cfg = {
    method,
    url,
    headers,
    json: opts.json !== false,
    returnFullResponse: true,
    timeout: opts.timeout || 30000,
  };
  if (opts.body !== undefined && opts.body !== null) {
    cfg.body = opts.body;
    if (typeof opts.body === 'object' && !headers['Content-Type'] && !headers['content-type']) {
      cfg.headers['Content-Type'] = 'application/json';
    }
  }
  let res;
  try {
    res = await __helpers.httpRequest(cfg);
  } catch (err) {
    const status = err.httpCode || err.statusCode || (err.response && err.response.status) || 0;
    const body = (err.response && err.response.body) || err.body || null;
    const wrapped = new Error('HTTP ' + (status || 'network') + ': ' + (err.message || String(err)).slice(0, 300));
    wrapped.httpCode = status;
    wrapped.body = body;
    throw wrapped;
  }
  const status = res.statusCode || res.status || 0;
  const body = res.body !== undefined ? res.body : res;
  if (status < 200 || status >= 300) {
    const e = new Error('HTTP ' + status + ': ' + String(body).slice(0, 300));
    e.httpCode = status;
    e.body = body;
    throw e;
  }
  return body;
}


const fetch = async (url, options = {}) => {
  const opts = {
    method: options.method || 'GET',
    url: url,
    headers: options.headers || {},
    json: true,
    ignoreHttpStatusErrors: true
  };
  if (options.body) {
    opts.body = typeof options.body === 'string' ? JSON.parse(options.body) : options.body;
  }
  const res = await __httpRequest(opts);
  return {
    json: async () => res,
    ok: true,
    status: 200
  };
};

const proposal = $input.first().json;

if (proposal.skip) {
  return [{ json: { skip: true, message: proposal.message } }];
}

const N8N_URL = 'https://krishraja10101.app.n8n.cloud/api/v1';
const N8N_KEY = '{{N8N_API_JWT}}';
const SUPABASE_URL = 'https://gojpffsrxybbpbdzzrvs.supabase.co';
const SUPABASE_KEY = '{{SUPABASE_SERVICE_ROLE_KEY}}';

const results = { proposalId: proposal.id, title: proposal.title, actions: [] };

try {
  // Step A: If there is a current workflow, create a backup
  let rollbackId = null;
  if (proposal.current_workflow_id) {
    const wfResp = await fetch(`${N8N_URL}/workflows/${proposal.current_workflow_id}`, {
      headers: { 'X-N8N-API-KEY': N8N_KEY }
    });
    const wf = await wfResp.json();

    if (wf && wf.nodes) {
      const today = new Date().toISOString().split('T')[0];
      const backupName = `[BACKUP] ${wf.name} - pre-change ${today}`;
      const backupResp = await fetch(`${N8N_URL}/workflows`, {
        method: 'POST',
        headers: { 'X-N8N-API-KEY': N8N_KEY, 'Content-Type': 'application/json' },
        body: JSON.stringify({
          name: backupName,
          nodes: wf.nodes,
          connections: wf.connections,
          settings: wf.settings || { executionOrder: 'v1' }
        })
      });
      const backup = await backupResp.json();
      rollbackId = backup.id;
      results.actions.push(`Backup created: ${backupName} (ID: ${rollbackId})`);
    }
  }

  // Step B: Apply proposed changes
  const changes = proposal.proposed_changes || {};
  if (proposal.current_workflow_id && (changes.nodes || changes.connections)) {
    const wfResp = await fetch(`${N8N_URL}/workflows/${proposal.current_workflow_id}`, {
      headers: { 'X-N8N-API-KEY': N8N_KEY }
    });
    const currentWf = await wfResp.json();

    let updatedNodes = currentWf.nodes || [];
    let updatedConnections = currentWf.connections || {};

    // Add new nodes
    if (changes.add_nodes) {
      updatedNodes = [...updatedNodes, ...changes.add_nodes];
    }
    // Remove nodes by id
    if (changes.remove_node_ids) {
      updatedNodes = updatedNodes.filter(n => !changes.remove_node_ids.includes(n.id));
    }
    // Replace nodes by id
    if (changes.replace_nodes) {
      for (const replacement of changes.replace_nodes) {
        const idx = updatedNodes.findIndex(n => n.id === replacement.id);
        if (idx >= 0) updatedNodes[idx] = replacement;
      }
    }
    // Update connections
    if (changes.connections) {
      updatedConnections = { ...updatedConnections, ...changes.connections };
    }
    // Full replacement of connections
    if (changes.replace_connections) {
      updatedConnections = changes.replace_connections;
    }

    const patchResp = await fetch(`${N8N_URL}/workflows/${proposal.current_workflow_id}`, {
      method: 'PUT',
      headers: { 'X-N8N-API-KEY': N8N_KEY, 'Content-Type': 'application/json' },
      body: JSON.stringify({
        name: currentWf.name,
        nodes: updatedNodes,
        connections: updatedConnections,
        settings: currentWf.settings || { executionOrder: 'v1' }
      })
    });
    const patchResult = await patchResp.json();
    results.actions.push(`Workflow ${proposal.current_workflow_id} updated with proposed changes`);
  } else if (changes.create_new) {
    // Create a brand new workflow from the proposal
    const createResp = await fetch(`${N8N_URL}/workflows`, {
      method: 'POST',
      headers: { 'X-N8N-API-KEY': N8N_KEY, 'Content-Type': 'application/json' },
      body: JSON.stringify({
        name: changes.create_new.name || proposal.title,
        nodes: changes.create_new.nodes || [],
        connections: changes.create_new.connections || {},
        settings: changes.create_new.settings || { executionOrder: 'v1' }
      })
    });
    const newWf = await createResp.json();
    results.actions.push(`New workflow created: ${newWf.name} (ID: ${newWf.id})`);
  }

  // Step C: Compute quality baseline from last 10 runs
  let qualityBaseline = null;
  if (proposal.current_workflow_id) {
    const runsResp = await fetch(
      `${SUPABASE_URL}/rest/v1/workflow_runs?workflow_id=eq.${proposal.current_workflow_id}&order=run_at.desc&limit=10`,
      { headers: { 'apikey': SUPABASE_KEY, 'Authorization': `Bearer ${SUPABASE_KEY}` } }
    );
    const runs = await runsResp.json();
    if (runs && runs.length > 0) {
      const scores = runs.filter(r => r.quality_score != null).map(r => parseFloat(r.quality_score));
      if (scores.length > 0) {
        qualityBaseline = scores.reduce((a, b) => a + b, 0) / scores.length;
      }
    }
  }

  // Step D: Update proposal status to 'executing'
  const now = new Date().toISOString();
  const updateBody = {
    status: 'executing',
    executed_at: now,
    updated_at: now
  };
  if (rollbackId) updateBody.rollback_workflow_id = rollbackId;
  if (qualityBaseline !== null) updateBody.quality_baseline = qualityBaseline;

  await fetch(
    `${SUPABASE_URL}/rest/v1/workflow_proposals?id=eq.${proposal.id}`,
    {
      method: 'PATCH',
      headers: {
        'apikey': SUPABASE_KEY,
        'Authorization': `Bearer ${SUPABASE_KEY}`,
        'Content-Type': 'application/json',
        'Prefer': 'return=minimal'
      },
      body: JSON.stringify(updateBody)
    }
  );
  results.actions.push('Proposal status updated to executing');
  results.status = 'executing';
  results.rollbackId = rollbackId;
  results.qualityBaseline = qualityBaseline;

} catch (err) {
  results.error = err.message;
  results.status = 'error';
}

return [{ json: results }];

