const SUPABASE_URL = 'https://gojpffsrxybbpbdzzrvs.supabase.co';
const SUPABASE_KEY = '{{SUPABASE_SERVICE_ROLE_KEY}}';

const proposals = await __httpRequest({
  method: 'GET',
  url: `${SUPABASE_URL}/rest/v1/workflow_proposals?status=eq.approved&order=approved_at`,
  headers: {
    'apikey': SUPABASE_KEY,
    'Authorization': `Bearer ${SUPABASE_KEY}`
  },
  json: true
});

if (!proposals || proposals.length === 0) {
  return [{ json: { skip: true, message: 'No approved proposals found' } }];
}

return proposals.map(p => ({ json: p }));
